-- «رزرو ۴ روزه» (purchase step 19): a paid order held for a few days, so the customer's next orders to the same address
-- join it and ship together, with one shipping cost (roadmap section 13).
--
-- A plain table: a group's life is short (HOLDING, then RELEASED) and its orders keep their own story in their events.
-- Every change takes the customer's lock first (pg_advisory_xact_lock, section 11 lock 4) and checks the row's version.

CREATE SEQUENCE reservationgroupid_seq START WITH 1001;

CREATE TABLE reservationgroup_tbl
(
    "pId"                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "groupId"            BIGINT      NOT NULL UNIQUE CHECK ("groupId" > 0),
    -- The panel's shipmentGroupCode, made from the id.
    code                 VARCHAR(24) NOT NULL UNIQUE CHECK (code ~ '^SG-[1-9][0-9]*$'),
    -- Logistics, not a financial record: a group goes with its account.
    "userId"             BIGINT      NOT NULL REFERENCES user_tbl ("pId") ON DELETE CASCADE,
    -- The order that started it; no foreign key, as orderqm_tbl is a read model.
    "rootOrderId"        BIGINT      NOT NULL CHECK ("rootOrderId" > 0),
    -- The saved address of that order, or null when it went to an address not kept; and what that address said then.
    "addressId"          BIGINT CHECK ("addressId" > 0),
    "addressFingerprint" BYTEA       NOT NULL CHECK (length("addressFingerprint") = 32),
    "shippingMethod"     VARCHAR(10) NOT NULL CHECK ("shippingMethod" IN ('TIPAX', 'POST', 'COURIER')),
    -- When its first order was paid, and that plus the hold days: fixed, never extended.
    "startedOn"          TIMESTAMPTZ NOT NULL,
    "expiresOn"          TIMESTAMPTZ NOT NULL CHECK ("expiresOn" > "startedOn"),
    status               VARCHAR(10) NOT NULL CHECK (status IN ('HOLDING', 'RELEASED')),
    "releasedOn"         TIMESTAMPTZ,
    version              BIGINT      NOT NULL DEFAULT 0,

    CONSTRAINT reservationgroup_tbl_released_check CHECK ((status = 'RELEASED') = ("releasedOn" IS NOT NULL))
);

-- A customer holds at most one reservation at a time.
CREATE UNIQUE INDEX reservationgroup_one_holding_idx ON reservationgroup_tbl ("userId") WHERE status = 'HOLDING';

-- The release job's search.
CREATE INDEX reservationgroup_due_idx ON reservationgroup_tbl ("expiresOn") WHERE status = 'HOLDING';

-- The group an order is in: the release job finds a group's held orders by it, and the reservation's page its orders.
ALTER TABLE orderqm_tbl ADD COLUMN "reservationGroupId" BIGINT CHECK ("reservationGroupId" > 0);
CREATE INDEX orderqm_reservation_group_idx ON orderqm_tbl ("reservationGroupId") WHERE "reservationGroupId" IS NOT NULL;

-- Round 2 is here: the shop offers «رزرو ۴ روزه».
UPDATE shopsettings_tbl SET "reservationEnabled" = TRUE, "updatedOn" = now();
